#!/usr/bin/env bash
# LAST GPU ATTEMPT. rocprofv3 1.1.0 rev 97f5574fe -- the SAME revision that wrote
# 85,737 dispatch rows on this board on 2026-09-07 -- now dies at OUTPUT
# GENERATION with ring_buffer.cpp:106 "mmap failed with errno 22 :: Invalid
# argument", FATAL-aborts, and then DEADLOCKS in its own signal handler ignoring
# SIGTERM. Runtime tracing is fine: 4.804 tok/s profiled vs 4.823 unprofiled.
# The 2026-09-07 run used a purpose-built podman image; this worker is bare
# noble with the same packages, so the suspect is the ENVIRONMENT.
set -u
if [ "${KA_STAGED:-0}" != "1" ]; then
  cp -f "$0" /tmp/ka6-staged.sh && chmod +x /tmp/ka6-staged.sh && exec env KA_STAGED=1 bash /tmp/ka6-staged.sh
  exit 80
fi
L=/tmp/kattrib; BLD=$L/build
B27=/tmp/kattrib-27b/Qwen3.8-27B-Q4_K_M.gguf
Q4E=/tmp/ckpt-iq1s/Qwen3.8-Flash-Next-UD-IQ1_S-00001-of-00003.gguf
OUT=/workspace/rocm-kernel-attrib/w4-$(date -u +%Y%m%dT%H%M%SZ); mkdir -p "$OUT"
exec 2>&1
( while true; do echo "[hb] $(date -u +%H:%M:%S)"; sleep 120; done ) & HB=$!
trap 'kill $HB 2>/dev/null' EXIT INT TERM
export PATH=/opt/rocm/bin:/opt/rocm/llvm/bin:$PATH
export LD_LIBRARY_PATH=/opt/rocm/lib:${LD_LIBRARY_PATH:-}
say(){ echo; echo "===== $* ====="; date -u +%FT%TZ; }
echo "" | base64 -d > /tmp/rank.py; echo "rank.py bytes=$(stat -c%s /tmp/rank.py)"
CLI=$(find "$BLD" -name vllm-cli -type f -perm -u+x|head -1); echo "CLI=$CLI"

say "A. THE MAPPING LIMITS THE RING BUFFER LIVES UNDER"
for k in vm.max_map_count vm.overcommit_memory vm.overcommit_ratio; do echo "$k = $(sysctl -n $k 2>&1)"; done
echo "ulimit -l = $(ulimit -l);  ulimit -v = $(ulimit -v);  ulimit -m = $(ulimit -m)"
echo "--- raising vm.max_map_count, which a 1224-tensor mmap load can exhaust ---"
sysctl -w vm.max_map_count=2097152 2>&1 | sed 's/^/   /'
echo "now vm.max_map_count = $(sysctl -n vm.max_map_count 2>&1)"

run_leg(){ # run_leg <tag> <fmt> <model> <ngen> <rep> <tmo>
  local tag=$1 fmt=$2 model=$3 ngen=$4 rep=$5 tmo=$6
  local D=$L/w4-$tag; rm -rf "$D"; mkdir -p "$D/trace"
  say "LEG[$tag] fmt=$fmt model=$(basename "$model") ngen=$ngen rep=$rep"
  local S0=$(date +%s)
  timeout -k 30 --foreground "$tmo" rocprofv3 --kernel-trace --output-format "$fmt" \
      --output-directory "$D/trace" -- "$CLI" --model "$model" --device auto \
      --prompt 'The capital of France is' --max-tokens "$ngen" --temperature 0 \
      --max-num-seqs 1 --repeat "$rep" > "$D/out.txt" 2> "$D/err.txt" </dev/null
  local r=$?; echo "LEG[$tag] rc=$r wall=$(( $(date +%s) - S0 ))s"
  grep -a "tok_s=" "$D/err.txt"|sed "s/^/$tag  /"
  grep -aE "ring_buffer|mmap failed|Opened result file" "$D/err.txt"|head -4|sed "s/^/$tag  /"
  echo "$tag  files:"; find "$D/trace" -type f -printf '   %s bytes  %p\n' 2>/dev/null|head -8
  local KT=$(find "$D/trace" -name '*kernel_trace.csv' 2>/dev/null|head -1)
  if [ -n "$KT" ] && [ "$(wc -l < "$KT")" -gt 1 ]; then
    echo "$tag  ROWS=$(( $(wc -l < "$KT") - 1 ))  <- NON-EMPTY, ranking it"
    SW=$(grep -aci "swap" "$D/err.txt")
    python3 /tmp/rank.py "$KT" --skip-first 1 --swap-warnings "$SW" --top 30 \
        --json "$OUT/$tag-rank.json" 2>&1 | sed "s/^/$tag  /"
    gzip -9 -c "$KT" > "$OUT/$tag-kernel_trace.csv.gz"
    return 0
  fi
  echo "$tag  NO USABLE CSV"
  return 1
}

say "B. 27B CONTROL under the raised limit"
run_leg M27 csv "$B27" 40 3 900 && GOOD27=1 || GOOD27=0
echo "GOOD27=$GOOD27"

say "C. QWEN4_EXP -- the deliverable"
run_leg MQ4 csv "$Q4E" 24 3 1500 && GOODQ4=1 || GOODQ4=0
echo "GOODQ4=$GOODQ4"

say "D. ARCHIVE"
for t in M27 MQ4; do gzip -9 -c "$L/w4-$t/err.txt" > "$OUT/$t-err.txt.gz" 2>/dev/null; done
ls -la "$OUT"
say "DONE /workspace $OUT"
